import { Mic, Loader2, Volume2, AlertCircle } from 'lucide-react';

// Visual states for the Gemini-style voice-first flow. `state` is optional —
// omitting it (or passing nothing) falls back to the original two-state
// (listening / not) look, so any existing caller keeps working unchanged.
export const VOICE_BUTTON_STATE = {
  IDLE: 'idle',
  LISTENING: 'listening',
  THINKING: 'thinking',
  SPEAKING: 'speaking',
  ERROR: 'error',
};

export default function VoiceButton({
  disabled = true,
  listening = false,
  state,
  onClick,
}) {
  // Backward-compatible resolution: an explicit `state` wins; otherwise
  // derive it from the old boolean so legacy call sites are unaffected.
  const resolvedState =
    state ?? (listening ? VOICE_BUTTON_STATE.LISTENING : VOICE_BUTTON_STATE.IDLE);

  const stateConfig = {
    [VOICE_BUTTON_STATE.IDLE]: {
      icon: Mic,
      label: disabled ? 'Voice input — coming soon' : 'Start voice input',
      title: disabled ? 'Voice input coming soon' : 'Speak your answer',
    },
    [VOICE_BUTTON_STATE.LISTENING]: {
      icon: Mic,
      label: 'Listening — tap to stop',
      title: 'Listening…',
    },
    [VOICE_BUTTON_STATE.THINKING]: {
      icon: Loader2,
      label: 'Thinking…',
      title: 'Thinking…',
      spin: true,
    },
    [VOICE_BUTTON_STATE.SPEAKING]: {
      icon: Volume2,
      label: 'Speaking — tap to interrupt',
      title: 'Speaking…',
    },
    [VOICE_BUTTON_STATE.ERROR]: {
      icon: AlertCircle,
      label: 'Voice error — tap to retry',
      title: 'Something went wrong',
    },
  }[resolvedState];

  const Icon = stateConfig.icon;

  return (
    <button
      type="button"
      className={[
        'rl-input-bar__mic',
        resolvedState === VOICE_BUTTON_STATE.LISTENING && 'rl-input-bar__mic--listening',
        resolvedState === VOICE_BUTTON_STATE.THINKING && 'rl-input-bar__mic--thinking',
        resolvedState === VOICE_BUTTON_STATE.SPEAKING && 'rl-input-bar__mic--speaking',
        resolvedState === VOICE_BUTTON_STATE.ERROR && 'rl-input-bar__mic--error',
      ]
        .filter(Boolean)
        .join(' ')}
      onClick={onClick}
      disabled={disabled}
      aria-label={stateConfig.label}
      title={stateConfig.title}
    >
      <Icon size={17} strokeWidth={2.2} className={stateConfig.spin ? 'rl-spin' : undefined} />
    </button>
  );
}
